pub enum Msg {
    Ping,
    Hello(String),
}

pub fn decode(bytes: &str) -> Result<Msg, String> {
    if bytes.contains("ping") {
        return Ok(Msg::Ping);
    }
    if let Some(value) = bytes.strip_prefix("v:2|hello:") {
        return Ok(Msg::Hello(value.into()));
    }
    eprintln!("decode error: unknown message");
    Err("unknown".into())
}

pub fn encode(msg: &Msg) -> String {
    match msg {
        Msg::Ping => "ping".into(),
        Msg::Hello(value) => format!("v:2|hello:{value}"),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn encode_roundtrip_ping() {
        let encoded = encode(&Msg::Ping);
        assert!(matches!(decode(&encoded), Ok(Msg::Ping)));
    }

    #[test]
    fn ping_roundtrips() {
        encode_roundtrip_ping();
    }

    #[test]
    fn hello_roundtrips_with_v2_envelope() {
        let encoded = encode(&Msg::Hello("client".into()));
        assert_eq!(encoded, "v:2|hello:client");
        assert!(matches!(decode(&encoded), Ok(Msg::Hello(value)) if value == "client"));
    }

    #[test]
    fn malformed_v2_message_is_rejected() {
        assert!(decode("v:1|hello:client").is_err());
    }
}

